DROP TABLE orders;
CREATE TABLE orders (status VARCHAR(255) NOT NULL, placed_at DATETIME DEFAULT NULL, id CHAR(36) NOT NULL, customer_id CHAR(36) NOT NULL, currency VARCHAR(255) NOT NULL, discount_amount_in_cents INTEGER NOT NULL, discount_currency VARCHAR(255) NOT NULL, cancellation_note CLOB DEFAULT NULL, refund_due_amount_in_cents INTEGER NOT NULL, refund_due_currency VARCHAR(255) NOT NULL, PRIMARY KEY (id));
INSERT INTO orders (status, placed_at, id, customer_id, currency, discount_amount_in_cents, discount_currency, cancellation_note, refund_due_amount_in_cents, refund_due_currency) SELECT status, placed_at, id, customer_id, currency, discount_amount_in_cents, discount_currency, cancellation_note, refund_due_amount_in_cents, refund_due_currency FROM __temp__orders;
DROP TABLE __temp__orders;

